   135          0,0,0,0, 0,0,0,0,                               // 0000xxxx - 0111xxxx
   136          1,1,1,1,                                        // 1000xxxx - 1011xxxx
   137          2,2,                                            // 1100xxxx - 1101xxxx
   138          3,                                              // 1110xxxx
   139          4,                                              // 1111xxxx
   140      };
